"""Deficit Guard Service - Deterministic detection, statutory checklist validation, and interactive chip annotation for legal drafts."""

import re
from typing import Any
from app.schemas.drafting import DeficitItem, DraftingTemplateId

# Regex to match deficit placeholders generated by LLM or advocate:
# Matches:
# [REQUIRED: Date of Notice]
# [CRITICAL: Police Station Name]
# [CRITICAL MISSING FACT: Cheque Amount]
# [MISSING VARIABLE: FIR Number]
DEFICIT_REGEX = re.compile(
    r"\[(?:REQUIRED|CRITICAL(?:\s+MISSING\s+FACT)?|MISSING\s+VARIABLE)[:\s]+([^\]]+)\]",
    re.IGNORECASE,
)

# Template statutory checklist rules to catch unflagged missing items
TEMPLATE_STATUTORY_REQUIREMENTS: dict[str, list[dict[str, Any]]] = {
    "CRIMINAL_ANTICIPATORY_BAIL": [
        {
            "key": "fir_details",
            "label": "FIR / Complaint Reference",
            "patterns": [r"FIR\s*(?:No\.?|Number)", r"Crime\s*No", r"Complaint\s*Dated"],
            "placeholder": "[CRITICAL MISSING FACT: FIR or Criminal Complaint Number]",
            "severity": "CRITICAL",
            "description": "Essential for Sessions Court or High Court to issue notice to State.",
        },
        {
            "key": "apprehension_ground",
            "label": "Ground for Apprehension of Arrest",
            "patterns": [r"apprehends?\s*arrest", r"reason\s*to\s*believe", r"threat\s*of\s*arrest", r"police\s*visited"],
            "placeholder": "[REQUIRED: Specific Basis or Threat of Imminent Arrest]",
            "severity": "CRITICAL",
            "description": "Condition precedent under Section 438 CrPC / 482 BNSS.",
        },
        {
            "key": "custodial_necessity",
            "label": "Absence of Custodial Need",
            "patterns": [r"custodial\s*(?:interrogation|investigation)", r"no\s*recovery", r"clean\s*antecedents"],
            "placeholder": "[REQUIRED: Grounds Demonstrating Custodial Interrogation is Unnecessary]",
            "severity": "RECOMMENDED",
            "description": "Key criteria under Gurbaksh Singh Sibbia / Sushila Aggarwal.",
        },
    ],
    "CRIMINAL_SECTION_138_NI": [
        {
            "key": "cheque_dishonour_date",
            "label": "Cheque Return Memo Date & Reason",
            "patterns": [r"return\s*memo", r"memo\s*dated", r"insufficient\s*funds", r"account\s*closed", r"funds\s*insufficient"],
            "placeholder": "[CRITICAL MISSING FACT: Bank Return Memo Date and Dishonour Reason]",
            "severity": "CRITICAL",
            "description": "Essential to prove cheque was presented within validity and dishonoured.",
        },
        {
            "key": "statutory_demand_notice",
            "label": "15-Day Statutory Demand Notice Date",
            "patterns": [r"statutory\s*(?:demand\s*)?notice", r"demand\s*notice\s*dated", r"notice\s*under\s*section\s*138"],
            "placeholder": "[CRITICAL MISSING FACT: Date of Statutory Demand Notice & Delivery]",
            "severity": "CRITICAL",
            "description": "Notice must be dispatched within 30 days of memo and give 15 days to pay.",
        },
    ],
    "CIVIL_WRIT_PETITION": [
        {
            "key": "impugned_order",
            "label": "Impugned Order / Action Details",
            "patterns": [r"impugned\s*(?:order|action|directive|notification)", r"annexure\s*p[-_]?\d+", r"dated\s*\d{1,2}[\.\/-]\d{1,2}[\.\/-]\d{2,4}"],
            "placeholder": "[CRITICAL MISSING FACT: Date and Particulars of Impugned Order/Action]",
            "severity": "CRITICAL",
            "description": "Necessary for prayer in Certiorari or Mandamus.",
        },
        {
            "key": "alternative_remedy",
            "label": "Absence of Alternative Remedy Averment",
            "patterns": [r"alternative\s*(?:efficacious\s*)?remedy", r"no\s*other\s*(?:equally\s*)?efficacious", r"efficacious\s*remedy"],
            "placeholder": "[REQUIRED: Averment on Non-Availability of Alternative Statutory Remedy]",
            "severity": "RECOMMENDED",
            "description": "Mandatory formal averment for maintainability under Article 226/32.",
        },
    ],
}


class DeficitGuardService:
    """Service for auditing, extracting, and highlighting deficits in pleadings."""

    def scan_deficits(self, text_or_html: str, template_id: str | None = None) -> list[DeficitItem]:
        """Scans draft content and returns all detected deficits."""
        deficits: list[DeficitItem] = []
        seen_keys: set[str] = set()

        # 1. Regex search for explicit placeholders generated by LLM
        for match in DEFICIT_REGEX.finditer(text_or_html):
            raw_placeholder = match.group(0)
            desc = match.group(1).strip()
            key = re.sub(r"[^a-zA-Z0-9_]+", "_", desc.lower())[:32]

            if key not in seen_keys:
                seen_keys.add(key)
                severity = "CRITICAL" if any(w in raw_placeholder.upper() for w in ["CRITICAL", "FIR", "DATE", "AMOUNT"]) else "RECOMMENDED"
                deficits.append(
                    DeficitItem(
                        placeholder=raw_placeholder,
                        variable_key=key,
                        field_label=desc[:40],
                        severity=severity,
                        description=f"Missing factual link: {desc}",
                    )
                )

        # 2. Check template-specific statutory rules if provided
        if template_id and template_id in TEMPLATE_STATUTORY_REQUIREMENTS:
            rules = TEMPLATE_STATUTORY_REQUIREMENTS[template_id]
            for rule in rules:
                rule_key = rule["key"]
                if rule_key not in seen_keys:
                    # Check if any pattern matches in the text
                    has_match = any(re.search(pat, text_or_html, re.IGNORECASE) for pat in rule["patterns"])
                    if not has_match:
                        seen_keys.add(rule_key)
                        deficits.append(
                            DeficitItem(
                                placeholder=rule["placeholder"],
                                variable_key=rule_key,
                                field_label=rule["label"],
                                severity=rule["severity"],
                                description=rule["description"],
                            )
                        )

        return deficits

    def annotate_html_with_deficit_chips(self, html_content: str) -> str:
        """Wraps deficit placeholders in interactive HTML mark tags for the editor."""
        def replace_deficit(match: re.Match) -> str:
            raw = match.group(0)
            desc = match.group(1).strip()
            key = re.sub(r"[^a-zA-Z0-9_]+", "_", desc.lower())[:32]
            return (
                f'<mark class="court-deficit-chip" data-deficit-key="{key}" data-placeholder="{raw}" '
                f'title="Missing Court Detail - Click to Fill">'
                f'{raw}'
                f'</mark>'
            )

        return DEFICIT_REGEX.sub(replace_deficit, html_content)


deficit_guard_service = DeficitGuardService()

